INSERT INTO questions (id, content_type, skill, question_type, tier, question_text, answer, accepted_answers, explanation, audio_url, metadata) VALUES (91, 'VOCABULARY', 'READING', 'MULT_CHOICE', 1, 'What does "mortgage" mean?', 'khoản vay mua nhà (thế chấp)', '[]'::jsonb, '"mortgage" /ˈmɔːɡɪdʒ/ nghĩa là khoản vay mua nhà (thế chấp). Ví dụ: They took out a 20-year mortgage to buy their first home.', NULL, '{"options": ["giấy/chế độ bảo hành", "khoản vay mua nhà (thế chấp)", "thợ sửa ống nước", "lắp đặt"]}'::jsonb);
