INSERT INTO questions (id, content_type, skill, question_type, tier, question_text, answer, accepted_answers, explanation, audio_url, metadata) VALUES (92, 'VOCABULARY', 'WRITING', 'FILL_BLANK', 2, 'Điền từ còn thiếu (gợi ý: khoản vay mua nhà (thế chấp))', 'mortgage', '["mortgages"]'::jsonb, '"Mortgage" là khoản vay ngân hàng để mua nhà, lấy chính căn nhà làm tài sản bảo đảm. Chữ "t" câm: đọc là MOR-gij.', NULL, '{"sentence": "We borrowed money from the bank and will pay the ___ for twenty years.", "hint": "m _ _ _ _ _ _ e"}'::jsonb);
INSERT INTO question_vocabularies (question_id, vocabulary_id, relation_type) VALUES (92, 31, 'TARGET');
INSERT INTO questions (id, content_type, skill, question_type, tier, question_text, answer, accepted_answers, explanation, audio_url, metadata) VALUES (93, 'VOCABULARY', 'WRITING', 'FILL_BLANK', 3, 'Điền một từ phù hợp vào chỗ trống', 'mortgage', '["mortgages"]'::jsonb, 'Ngân hàng duyệt khoản vay mua nhà → "mortgage". "Rent" là tiền thuê trả cho chủ nhà, không cần ngân hàng duyệt.', NULL, '{"sentence": "The bank approved our ___, so we can finally buy the house."}'::jsonb);
