INSERT INTO questions (id, content_type, skill, question_type, tier, question_text, answer, accepted_answers, explanation, audio_url, metadata) VALUES (108, 'VOCABULARY', 'WRITING', 'FILL_BLANK', 3, 'Điền một từ phù hợp vào chỗ trống', 'vacancy', '["vacancies"]'::jsonb, '"No vacancy" là hết chỗ. "Deposit" là tiền cọc, không ai treo biển "No deposit" để báo hết phòng.', NULL, '{"sentence": "The sign says \"No ___\", so all the rooms are already taken."}'::jsonb);
