INSERT INTO questions (id, content_type, skill, question_type, tier, question_text, answer, accepted_answers, explanation, audio_url, metadata) VALUES (109, 'VOCABULARY', 'READING', 'MULT_CHOICE', 1, 'What does "furnished" mean?', 'có sẵn đồ đạc', '[]'::jsonb, '"furnished" /ˈfɜːnɪʃt/ nghĩa là có sẵn đồ đạc. Ví dụ: The apartment comes fully furnished, so you only need your clothes.', NULL, '{"options": ["nhà thầu (người nhận làm công trình)", "việc giao hàng", "hàng người (xếp hàng chờ)", "có sẵn đồ đạc"]}'::jsonb);
INSERT INTO question_vocabularies (question_id, vocabulary_id, relation_type) VALUES (109, 37, 'TARGET');
INSERT INTO questions (id, content_type, skill, question_type, tier, question_text, answer, accepted_answers, explanation, audio_url, metadata) VALUES (110, 'VOCABULARY', 'WRITING', 'FILL_BLANK', 2, 'Điền từ còn thiếu (gợi ý: có sẵn đồ đạc)', 'furnished', '[]'::jsonb, '"Furnished" = đã có đồ nội thất (từ "furniture"). Ngược lại là "unfurnished" — nhà trống.', NULL, '{"sentence": "The flat is ___, with a bed, a sofa and a dining table already inside.", "hint": "f _ _ _ _ _ _ _ d"}'::jsonb);
INSERT INTO question_vocabularies (question_id, vocabulary_id, relation_type) VALUES (110, 37, 'TARGET');
INSERT INTO questions (id, content_type, skill, question_type, tier, question_text, answer, accepted_answers, explanation, audio_url, metadata) VALUES (111, 'VOCABULARY', 'WRITING', 'FILL_BLANK', 3, 'Điền một từ phù hợp vào chỗ trống', 'furnished', '[]'::jsonb, 'Không phải mua giường bàn vì phòng đã có sẵn đồ → "furnished". "Spacious" chỉ nói phòng rộng, không nói có đồ đạc.', NULL, '{"sentence": "Since the room is ___, you will not need to buy a bed or a desk."}'::jsonb);
INSERT INTO question_vocabularies (question_id, vocabulary_id, relation_type) VALUES (111, 37, 'TARGET');
INSERT INTO questions (id, content_type, skill, question_type, tier, question_text, answer, accepted_answers, explanation, audio_url, metadata) VALUES (112, 'VOCABULARY', 'READING', 'MULT_CHOICE', 1, 'What does "occupant" mean?', 'người đang ở (trong nhà/phòng)', '[]'::jsonb, '"occupant" /ˈɒkjəpənt/ nghĩa là người đang ở (trong nhà/phòng). Ví dụ: The previous occupant left some boxes in the garage.', NULL, '{"options": ["người đang ở (trong nhà/phòng)", "(thuộc) khu dân cư", "sự đặt chỗ trước", "nhân viên thu ngân"]}'::jsonb);
INSERT INTO question_vocabularies (question_id, vocabulary_id, relation_type) VALUES (112, 38, 'TARGET');
INSERT INTO questions (id, content_type, skill, question_type, tier, question_text, answer, accepted_answers, explanation, audio_url, metadata) VALUES (113, 'VOCABULARY', 'WRITING', 'FILL_BLANK', 2, 'Điền từ còn thiếu (gợi ý: người đang ở (trong nhà/phòng))', 'occupant', '["occupants"]'::jsonb, '"Occupant" là người đang ở trong một nơi (dù thuê hay sở hữu). Gốc "occupy" = chiếm chỗ.', NULL, '{"sentence": "The current ___ of the apartment will move out at the end of the month.", "hint": "o _ _ _ _ _ _ t"}'::jsonb);
INSERT INTO question_vocabularies (question_id, vocabulary_id, relation_type) VALUES (113, 38, 'TARGET');
INSERT INTO questions (id, content_type, skill, question_type, tier, question_text, answer, accepted_answers, explanation, audio_url, metadata) VALUES (114, 'VOCABULARY', 'WRITING', 'FILL_BLANK', 3, 'Điền một từ phù hợp vào chỗ trống', 'occupant', '["occupants"]'::jsonb, 'Người từng ở trước đây → "former occupant". "Landlord" là chủ nhà, thường không ở chung căn hộ cho thuê.', NULL, '{"sentence": "Mail for the former ___ keeps arriving at our new address."}'::jsonb);
INSERT INTO question_vocabularies (question_id, vocabulary_id, relation_type) VALUES (114, 38, 'TARGET');
INSERT INTO questions (id, content_type, skill, question_type, tier, question_text, answer, accepted_answers, explanation, audio_url, metadata) VALUES (115, 'VOCABULARY', 'READING', 'MULT_CHOICE', 1, 'What does "renew" mean?', 'gia hạn', '[]'::jsonb, '"renew" /rɪˈnjuː/ nghĩa là gia hạn. Ví dụ: We decided to renew our lease for another year.', NULL, '{"options": ["đổi (hàng, tiền)", "gia hạn", "lắp đặt", "giấy/chế độ bảo hành"]}'::jsonb);
INSERT INTO question_vocabularies (question_id, vocabulary_id, relation_type) VALUES (115, 39, 'TARGET');
INSERT INTO questions (id, content_type, skill, question_type, tier, question_text, answer, accepted_answers, explanation, audio_url, metadata) VALUES (116, 'VOCABULARY', 'WRITING', 'FILL_BLANK', 2, 'Điền từ còn thiếu (gợi ý: gia hạn)', 'renew', '["renews", "renewed"]'::jsonb, '"Renew" = làm mới lại, gia hạn (hợp đồng, thẻ, hộ chiếu). Re- (lại) + new (mới).', NULL, '{"sentence": "Our lease ends in June, but we want to ___ it for one more year.", "hint": "r _ _ _ w"}'::jsonb);
INSERT INTO question_vocabularies (question_id, vocabulary_id, relation_type) VALUES (116, 39, 'TARGET');
INSERT INTO questions (id, content_type, skill, question_type, tier, question_text, answer, accepted_answers, explanation, audio_url, metadata) VALUES (117, 'VOCABULARY', 'WRITING', 'FILL_BLANK', 3, 'Điền một từ phù hợp vào chỗ trống', 'renew', '["renews", "renewed"]'::jsonb, 'Kéo dài hợp đồng để ở tiếp → "renew". "Relocate" là chuyển đi nơi khác — ngược lại với điều người viết muốn.', NULL, '{"sentence": "If you do not ___ the contract by Friday, you will have to move out."}'::jsonb);
INSERT INTO question_vocabularies (question_id, vocabulary_id, relation_type) VALUES (117, 39, 'TARGET');
INSERT INTO questions (id, content_type, skill, question_type, tier, question_text, answer, accepted_answers, explanation, audio_url, metadata) VALUES (118, 'VOCABULARY', 'READING', 'MULT_CHOICE', 1, 'What does "contractor" mean?', 'nhà thầu (người nhận làm công trình)', '[]'::jsonb, '"contractor" /kənˈtræktə(r)/ nghĩa là nhà thầu (người nhận làm công trình). Ví dụ: The contractor said the kitchen will be finished in two weeks.', NULL, '{"options": ["khoản chi phí", "thường xuyên", "nhà thầu (người nhận làm công trình)", "chỗ cất đồ; việc lưu trữ"]}'::jsonb);
INSERT INTO question_vocabularies (question_id, vocabulary_id, relation_type) VALUES (118, 40, 'TARGET');
INSERT INTO questions (id, content_type, skill, question_type, tier, question_text, answer, accepted_answers, explanation, audio_url, metadata) VALUES (119, 'VOCABULARY', 'WRITING', 'FILL_BLANK', 2, 'Điền từ còn thiếu (gợi ý: nhà thầu (người nhận làm công trình))', 'contractor', '["contractors"]'::jsonb, '"Contractor" là người/công ty ký hợp đồng (contract) để làm một công trình.', NULL, '{"sentence": "The ___ and his team will repaint the whole building next month.", "hint": "c _ _ _ _ _ _ _ _ r"}'::jsonb);
INSERT INTO question_vocabularies (question_id, vocabulary_id, relation_type) VALUES (119, 40, 'TARGET');
INSERT INTO questions (id, content_type, skill, question_type, tier, question_text, answer, accepted_answers, explanation, audio_url, metadata) VALUES (120, 'VOCABULARY', 'WRITING', 'FILL_BLANK', 3, 'Điền một từ phù hợp vào chỗ trống', 'contractor', '["contractors"]'::jsonb, 'Xin báo giá sửa mái từ nhiều đơn vị thi công → "contractors". "Tenants" là người thuê nhà, họ không báo giá sửa chữa.', NULL, '{"sentence": "We asked three ___s for a price before choosing one to fix the roof."}'::jsonb);
INSERT INTO question_vocabularies (question_id, vocabulary_id, relation_type) VALUES (120, 40, 'TARGET');
INSERT INTO questions (id, content_type, skill, question_type, tier, question_text, answer, accepted_answers, explanation, audio_url, metadata) VALUES (121, 'VOCABULARY', 'READING', 'MULT_CHOICE', 1, 'What does "residential" mean?', '(thuộc) khu dân cư', '[]'::jsonb, '"residential" /ˌrezɪˈdenʃl/ nghĩa là (thuộc) khu dân cư. Ví dụ: This is a quiet residential area with many families.', NULL, '{"options": ["bền", "lời/tin nhắc", "ở gần đó", "(thuộc) khu dân cư"]}'::jsonb);
INSERT INTO question_vocabularies (question_id, vocabulary_id, relation_type) VALUES (121, 41, 'TARGET');
INSERT INTO questions (id, content_type, skill, question_type, tier, question_text, answer, accepted_answers, explanation, audio_url, metadata) VALUES (122, 'VOCABULARY', 'WRITING', 'FILL_BLANK', 2, 'Điền từ còn thiếu (gợi ý: (thuộc) khu dân cư)', 'residential', '[]'::jsonb, '"Residential" = dành cho người ở. Gốc "reside" (cư trú), "resident" (cư dân).', NULL, '{"sentence": "They live in a ___ neighborhood, far from offices and factories.", "hint": "r _ _ _ _ _ _ _ _ _ l"}'::jsonb);
INSERT INTO question_vocabularies (question_id, vocabulary_id, relation_type) VALUES (122, 41, 'TARGET');
INSERT INTO questions (id, content_type, skill, question_type, tier, question_text, answer, accepted_answers, explanation, audio_url, metadata) VALUES (123, 'VOCABULARY', 'WRITING', 'FILL_BLANK', 3, 'Điền một từ phù hợp vào chỗ trống', 'residential', '[]'::jsonb, 'Toà nhà để ở (đối lập trung tâm mua sắm) → "residential". "Convenient" chỉ nói tiện lợi, không cho biết nhà để ở hay để buôn bán.', NULL, '{"sentence": "The city plans to build new ___ buildings instead of shopping malls."}'::jsonb);
INSERT INTO question_vocabularies (question_id, vocabulary_id, relation_type) VALUES (123, 41, 'TARGET');
INSERT INTO questions (id, content_type, skill, question_type, tier, question_text, answer, accepted_answers, explanation, audio_url, metadata) VALUES (124, 'VOCABULARY', 'READING', 'MULT_CHOICE', 1, 'What does "install" mean?', 'lắp đặt', '[]'::jsonb, '"install" /ɪnˈstɔːl/ nghĩa là lắp đặt. Ví dụ: A technician will install the new air conditioner tomorrow.', NULL, '{"options": ["lắp đặt", "lớp cách nhiệt/cách âm", "hoãn lại", "khoản vay mua nhà (thế chấp)"]}'::jsonb);
INSERT INTO question_vocabularies (question_id, vocabulary_id, relation_type) VALUES (124, 42, 'TARGET');
INSERT INTO questions (id, content_type, skill, question_type, tier, question_text, answer, accepted_answers, explanation, audio_url, metadata) VALUES (125, 'VOCABULARY', 'WRITING', 'FILL_BLANK', 2, 'Điền từ còn thiếu (gợi ý: lắp đặt)', 'install', '["installs", "installed"]'::jsonb, '"Install" = lắp đặt thiết bị (máy lạnh, đèn, cả phần mềm). In- (vào) + stall (đặt chỗ).', NULL, '{"sentence": "The company will ___ a new water heater in the bathroom.", "hint": "i _ _ _ _ _ l"}'::jsonb);
INSERT INTO question_vocabularies (question_id, vocabulary_id, relation_type) VALUES (125, 42, 'TARGET');
INSERT INTO questions (id, content_type, skill, question_type, tier, question_text, answer, accepted_answers, explanation, audio_url, metadata) VALUES (126, 'VOCABULARY', 'WRITING', 'FILL_BLANK', 3, 'Điền một từ phù hợp vào chỗ trống', 'install', '["installs", "installed"]'::jsonb, 'Đưa máy giặt mới vào và lắp cho chạy → "install". "Repair" là sửa đồ đã hỏng, không dùng cho máy mới.', NULL, '{"sentence": "It took the technician two hours to ___ the new washing machine."}'::jsonb);
INSERT INTO question_vocabularies (question_id, vocabulary_id, relation_type) VALUES (126, 42, 'TARGET');
INSERT INTO questions (id, content_type, skill, question_type, tier, question_text, answer, accepted_answers, explanation, audio_url, metadata) VALUES (127, 'VOCABULARY', 'READING', 'MULT_CHOICE', 1, 'What does "storage" mean?', 'chỗ cất đồ; việc lưu trữ', '[]'::jsonb, '"storage" /ˈstɔːrɪdʒ/ nghĩa là chỗ cất đồ; việc lưu trữ. Ví dụ: The apartment has plenty of storage space in the closets.', NULL, '{"options": ["bất động sản; tài sản", "chỗ cất đồ; việc lưu trữ", "tiền hoàn lại", "xác nhận"]}'::jsonb);
INSERT INTO question_vocabularies (question_id, vocabulary_id, relation_type) VALUES (127, 43, 'TARGET');
INSERT INTO questions (id, content_type, skill, question_type, tier, question_text, answer, accepted_answers, explanation, audio_url, metadata) VALUES (128, 'VOCABULARY', 'WRITING', 'FILL_BLANK', 2, 'Điền từ còn thiếu (gợi ý: chỗ cất đồ; việc lưu trữ)', 'storage', '[]'::jsonb, '"Storage" là chỗ để cất đồ. Gốc "store" (cất giữ) + -age.', NULL, '{"sentence": "There is extra ___ in the basement for your boxes.", "hint": "s _ _ _ _ _ e"}'::jsonb);
INSERT INTO question_vocabularies (question_id, vocabulary_id, relation_type) VALUES (128, 43, 'TARGET');
INSERT INTO questions (id, content_type, skill, question_type, tier, question_text, answer, accepted_answers, explanation, audio_url, metadata) VALUES (129, 'VOCABULARY', 'WRITING', 'FILL_BLANK', 3, 'Điền một từ phù hợp vào chỗ trống', 'storage', '[]'::jsonb, 'Thuê chỗ để cất quần áo mùa đông → "storage unit". "Furniture" là đồ đạc, không phải chỗ cất đồ.', NULL, '{"sentence": "Our apartment is small, so we rent a ___ unit for the winter clothes."}'::jsonb);
INSERT INTO question_vocabularies (question_id, vocabulary_id, relation_type) VALUES (129, 43, 'TARGET');
INSERT INTO questions (id, content_type, skill, question_type, tier, question_text, answer, accepted_answers, explanation, audio_url, metadata) VALUES (130, 'VOCABULARY', 'READING', 'MULT_CHOICE', 1, 'What does "durable" mean?', 'bền', '[]'::jsonb, '"durable" /ˈdjʊərəbl/ nghĩa là bền. Ví dụ: These floors are durable and easy to clean.', NULL, '{"options": ["có sẵn; rảnh", "sự kiểm tra (kỹ lưỡng)", "bền", "sự giảm giá"]}'::jsonb);
INSERT INTO question_vocabularies (question_id, vocabulary_id, relation_type) VALUES (130, 44, 'TARGET');
INSERT INTO questions (id, content_type, skill, question_type, tier, question_text, answer, accepted_answers, explanation, audio_url, metadata) VALUES (131, 'VOCABULARY', 'WRITING', 'FILL_BLANK', 2, 'Điền từ còn thiếu (gợi ý: bền)', 'durable', '[]'::jsonb, '"Durable" = dùng được lâu, khó hỏng. Liên tưởng "duration" (khoảng thời gian dài).', NULL, '{"sentence": "This sofa is made of ___ material, so it will last for many years.", "hint": "d _ _ _ _ _ e"}'::jsonb);
INSERT INTO question_vocabularies (question_id, vocabulary_id, relation_type) VALUES (131, 44, 'TARGET');
INSERT INTO questions (id, content_type, skill, question_type, tier, question_text, answer, accepted_answers, explanation, audio_url, metadata) VALUES (132, 'VOCABULARY', 'WRITING', 'FILL_BLANK', 3, 'Điền một từ phù hợp vào chỗ trống', 'durable', '[]'::jsonb, 'Đồ khó hỏng cho nhà có trẻ nhỏ → "durable". "Furnished" là "có sẵn đồ đạc", không nói tới độ bền.', NULL, '{"sentence": "Families with small children often choose ___ furniture that is hard to break."}'::jsonb);
INSERT INTO question_vocabularies (question_id, vocabulary_id, relation_type) VALUES (132, 44, 'TARGET');
INSERT INTO questions (id, content_type, skill, question_type, tier, question_text, answer, accepted_answers, explanation, audio_url, metadata) VALUES (133, 'VOCABULARY', 'READING', 'MULT_CHOICE', 1, 'What does "insulation" mean?', 'lớp cách nhiệt/cách âm', '[]'::jsonb, '"insulation" /ˌɪnsjuˈleɪʃn/ nghĩa là lớp cách nhiệt/cách âm. Ví dụ: Good insulation keeps the house warm in winter.', NULL, '{"options": ["việc giao hàng", "hàng người (xếp hàng chờ)", "thợ sửa ống nước", "lớp cách nhiệt/cách âm"]}'::jsonb);
INSERT INTO question_vocabularies (question_id, vocabulary_id, relation_type) VALUES (133, 45, 'TARGET');
INSERT INTO questions (id, content_type, skill, question_type, tier, question_text, answer, accepted_answers, explanation, audio_url, metadata) VALUES (134, 'VOCABULARY', 'WRITING', 'FILL_BLANK', 2, 'Điền từ còn thiếu (gợi ý: lớp cách nhiệt/cách âm)', 'insulation', '[]'::jsonb, '"Insulation" là lớp vật liệu chặn nhiệt hoặc tiếng ồn. Gốc "insulate" = cách ly.', NULL, '{"sentence": "The house stays cool in summer thanks to the ___ in the roof.", "hint": "i _ _ _ _ _ _ _ _ n"}'::jsonb);
INSERT INTO question_vocabularies (question_id, vocabulary_id, relation_type) VALUES (134, 45, 'TARGET');
INSERT INTO questions (id, content_type, skill, question_type, tier, question_text, answer, accepted_answers, explanation, audio_url, metadata) VALUES (135, 'VOCABULARY', 'WRITING', 'FILL_BLANK', 3, 'Điền một từ phù hợp vào chỗ trống', 'insulation', '[]'::jsonb, 'Hoá đơn sưởi giảm vì giữ nhiệt tốt hơn → "insulation". "Utilities" là chính các dịch vụ điện nước, không phải thứ được thay trên gác mái.', NULL, '{"sentence": "Our heating bills dropped after we replaced the old ___ in the attic."}'::jsonb);
INSERT INTO question_vocabularies (question_id, vocabulary_id, relation_type) VALUES (135, 45, 'TARGET');
INSERT INTO questions (id, content_type, skill, question_type, tier, question_text, answer, accepted_answers, explanation, audio_url, metadata) VALUES (136, 'VOCABULARY', 'READING', 'MULT_CHOICE', 1, 'What does "refund" mean?', 'tiền hoàn lại', '[]'::jsonb, '"refund" /ˈriːfʌnd/ nghĩa là tiền hoàn lại. Ví dụ: If the item is broken, you can ask for a full refund.', NULL, '{"options": ["tiền hoàn lại", "sự đặt chỗ trước", "nhân viên thu ngân", "chỗ rò rỉ"]}'::jsonb);
INSERT INTO question_vocabularies (question_id, vocabulary_id, relation_type) VALUES (136, 46, 'TARGET');
INSERT INTO questions (id, content_type, skill, question_type, tier, question_text, answer, accepted_answers, explanation, audio_url, metadata) VALUES (137, 'VOCABULARY', 'WRITING', 'FILL_BLANK', 2, 'Điền từ còn thiếu (gợi ý: tiền hoàn lại)', 'refund', '["refunds"]'::jsonb, '"Refund" = tiền được trả lại khi trả hàng. Re- (lại) + fund (tiền).', NULL, '{"sentence": "The shoes did not fit, so I returned them and got a ___.", "hint": "r _ _ _ _ d"}'::jsonb);
INSERT INTO question_vocabularies (question_id, vocabulary_id, relation_type) VALUES (137, 46, 'TARGET');
INSERT INTO questions (id, content_type, skill, question_type, tier, question_text, answer, accepted_answers, explanation, audio_url, metadata) VALUES (138, 'VOCABULARY', 'WRITING', 'FILL_BLANK', 3, 'Điền một từ phù hợp vào chỗ trống', 'refund', '["refunds"]'::jsonb, 'Cửa hàng hoàn tiền khi có biên lai → "refund". "Discount" là giảm giá lúc mua, không phải tiền trả lại sau khi mua.', NULL, '{"sentence": "Keep your receipt — without it, the store cannot give you a ___."}'::jsonb);
INSERT INTO question_vocabularies (question_id, vocabulary_id, relation_type) VALUES (138, 46, 'TARGET');
INSERT INTO questions (id, content_type, skill, question_type, tier, question_text, answer, accepted_answers, explanation, audio_url, metadata) VALUES (139, 'VOCABULARY', 'READING', 'MULT_CHOICE', 1, 'What does "discount" mean?', 'sự giảm giá', '[]'::jsonb, '"discount" /ˈdɪskaʊnt/ nghĩa là sự giảm giá. Ví dụ: Students get a ten percent discount at this café.', NULL, '{"options": ["phòng/chỗ còn trống", "sự giảm giá", "giấy/chế độ bảo hành", "đổi (hàng, tiền)"]}'::jsonb);
INSERT INTO question_vocabularies (question_id, vocabulary_id, relation_type) VALUES (139, 47, 'TARGET');
INSERT INTO questions (id, content_type, skill, question_type, tier, question_text, answer, accepted_answers, explanation, audio_url, metadata) VALUES (140, 'VOCABULARY', 'WRITING', 'FILL_BLANK', 2, 'Điền từ còn thiếu (gợi ý: sự giảm giá)', 'discount', '["discounts"]'::jsonb, '"Discount" = phần được giảm giá. Hay đi với "get/offer a discount on…".', NULL, '{"sentence": "This week there is a 20% ___ on all kitchen appliances.", "hint": "d _ _ _ _ _ _ t"}'::jsonb);
INSERT INTO question_vocabularies (question_id, vocabulary_id, relation_type) VALUES (140, 47, 'TARGET');
INSERT INTO questions (id, content_type, skill, question_type, tier, question_text, answer, accepted_answers, explanation, audio_url, metadata) VALUES (141, 'VOCABULARY', 'WRITING', 'FILL_BLANK', 3, 'Điền một từ phù hợp vào chỗ trống', 'discount', '["discounts"]'::jsonb, 'Thành viên mua nhiều được giảm giá → "discount". "Refund" chỉ có khi trả lại hàng.', NULL, '{"sentence": "Members receive a special ___ when they buy more than three books."}'::jsonb);
INSERT INTO question_vocabularies (question_id, vocabulary_id, relation_type) VALUES (141, 47, 'TARGET');
INSERT INTO questions (id, content_type, skill, question_type, tier, question_text, answer, accepted_answers, explanation, audio_url, metadata) VALUES (142, 'VOCABULARY', 'READING', 'MULT_CHOICE', 1, 'What does "delivery" mean?', 'việc giao hàng', '[]'::jsonb, '"delivery" /dɪˈlɪvəri/ nghĩa là việc giao hàng. Ví dụ: Delivery is free for orders over 30 dollars.', NULL, '{"options": ["thường xuyên", "có sẵn đồ đạc", "việc giao hàng", "khoản chi phí"]}'::jsonb);
INSERT INTO question_vocabularies (question_id, vocabulary_id, relation_type) VALUES (142, 48, 'TARGET');
INSERT INTO questions (id, content_type, skill, question_type, tier, question_text, answer, accepted_answers, explanation, audio_url, metadata) VALUES (143, 'VOCABULARY', 'WRITING', 'FILL_BLANK', 2, 'Điền từ còn thiếu (gợi ý: việc giao hàng)', 'delivery', '["deliveries"]'::jsonb, '"Delivery" = giao tận nơi. Động từ là "deliver".', NULL, '{"sentence": "We ordered pizza for ___ because nobody wanted to cook.", "hint": "d _ _ _ _ _ _ y"}'::jsonb);
INSERT INTO question_vocabularies (question_id, vocabulary_id, relation_type) VALUES (143, 48, 'TARGET');
INSERT INTO questions (id, content_type, skill, question_type, tier, question_text, answer, accepted_answers, explanation, audio_url, metadata) VALUES (144, 'VOCABULARY', 'WRITING', 'FILL_BLANK', 3, 'Điền một từ phù hợp vào chỗ trống', 'delivery', '["deliveries"]'::jsonb, 'Hứa giao hàng trong hai ngày làm việc → "delivery". "Reservation" là đặt chỗ trước, không phải giao hàng.', NULL, '{"sentence": "The online store promises ___ within two business days."}'::jsonb);
INSERT INTO question_vocabularies (question_id, vocabulary_id, relation_type) VALUES (144, 48, 'TARGET');
INSERT INTO questions (id, content_type, skill, question_type, tier, question_text, answer, accepted_answers, explanation, audio_url, metadata) VALUES (145, 'VOCABULARY', 'READING', 'MULT_CHOICE', 1, 'What does "reservation" mean?', 'sự đặt chỗ trước', '[]'::jsonb, '"reservation" /ˌrezəˈveɪʃn/ nghĩa là sự đặt chỗ trước. Ví dụ: I made a reservation for four people at seven o''clock.', NULL, '{"options": ["lời/tin nhắc", "ở gần đó", "người đang ở (trong nhà/phòng)", "sự đặt chỗ trước"]}'::jsonb);
INSERT INTO question_vocabularies (question_id, vocabulary_id, relation_type) VALUES (145, 49, 'TARGET');
INSERT INTO questions (id, content_type, skill, question_type, tier, question_text, answer, accepted_answers, explanation, audio_url, metadata) VALUES (146, 'VOCABULARY', 'WRITING', 'FILL_BLANK', 2, 'Điền từ còn thiếu (gợi ý: sự đặt chỗ trước)', 'reservation', '["reservations"]'::jsonb, '"Reservation" = đặt chỗ trước (bàn ăn, phòng, vé). Động từ "reserve".', NULL, '{"sentence": "The restaurant is always busy, so we made a ___ yesterday.", "hint": "r _ _ _ _ _ _ _ _ _ n"}'::jsonb);
INSERT INTO question_vocabularies (question_id, vocabulary_id, relation_type) VALUES (146, 49, 'TARGET');
INSERT INTO questions (id, content_type, skill, question_type, tier, question_text, answer, accepted_answers, explanation, audio_url, metadata) VALUES (147, 'VOCABULARY', 'WRITING', 'FILL_BLANK', 3, 'Điền một từ phù hợp vào chỗ trống', 'reservation', '["reservations"]'::jsonb, 'Nhà hàng/khách sạn tra tên khách đã đặt chỗ → "reservation". "Appointment" là lịch hẹn gặp người (bác sĩ, cố vấn), không dùng cho bàn ăn.', NULL, '{"sentence": "I''m sorry, but we don''t have a ___ under your name for tonight."}'::jsonb);
INSERT INTO question_vocabularies (question_id, vocabulary_id, relation_type) VALUES (147, 49, 'TARGET');
INSERT INTO questions (id, content_type, skill, question_type, tier, question_text, answer, accepted_answers, explanation, audio_url, metadata) VALUES (148, 'VOCABULARY', 'READING', 'MULT_CHOICE', 1, 'What does "warranty" mean?', 'giấy/chế độ bảo hành', '[]'::jsonb, '"warranty" /ˈwɒrənti/ nghĩa là giấy/chế độ bảo hành. Ví dụ: The laptop comes with a two-year warranty.', NULL, '{"options": ["giấy/chế độ bảo hành", "hoãn lại", "khoản vay mua nhà (thế chấp)", "gia hạn"]}'::jsonb);
INSERT INTO question_vocabularies (question_id, vocabulary_id, relation_type) VALUES (148, 50, 'TARGET');
INSERT INTO questions (id, content_type, skill, question_type, tier, question_text, answer, accepted_answers, explanation, audio_url, metadata) VALUES (149, 'VOCABULARY', 'WRITING', 'FILL_BLANK', 2, 'Điền từ còn thiếu (gợi ý: giấy/chế độ bảo hành)', 'warranty', '["warranties"]'::jsonb, '"Warranty" = cam kết sửa/đổi miễn phí trong một thời gian. "Under warranty" = còn bảo hành.', NULL, '{"sentence": "If the camera breaks this year, the ___ will cover the repair.", "hint": "w _ _ _ _ _ _ y"}'::jsonb);
INSERT INTO question_vocabularies (question_id, vocabulary_id, relation_type) VALUES (149, 50, 'TARGET');
INSERT INTO questions (id, content_type, skill, question_type, tier, question_text, answer, accepted_answers, explanation, audio_url, metadata) VALUES (150, 'VOCABULARY', 'WRITING', 'FILL_BLANK', 3, 'Điền một từ phù hợp vào chỗ trống', 'warranty', '["warranties"]'::jsonb, '"Under warranty" = còn trong thời hạn bảo hành. "Receipt" chỉ là biên lai, không ai nói "under receipt".', NULL, '{"sentence": "The washing machine stopped working, but luckily it is still under ___."}'::jsonb);
INSERT INTO question_vocabularies (question_id, vocabulary_id, relation_type) VALUES (150, 50, 'TARGET');
INSERT INTO questions (id, content_type, skill, question_type, tier, question_text, answer, accepted_answers, explanation, audio_url, metadata) VALUES (151, 'VOCABULARY', 'READING', 'MULT_CHOICE', 1, 'What does "expense" mean?', 'khoản chi phí', '[]'::jsonb, '"expense" /ɪkˈspens/ nghĩa là khoản chi phí. Ví dụ: Rent is our biggest monthly expense.', NULL, '{"options": ["nhà thầu (người nhận làm công trình)", "khoản chi phí", "xác nhận", "bất động sản; tài sản"]}'::jsonb);
INSERT INTO question_vocabularies (question_id, vocabulary_id, relation_type) VALUES (151, 51, 'TARGET');
INSERT INTO questions (id, content_type, skill, question_type, tier, question_text, answer, accepted_answers, explanation, audio_url, metadata) VALUES (152, 'VOCABULARY', 'WRITING', 'FILL_BLANK', 2, 'Điền từ còn thiếu (gợi ý: khoản chi phí)', 'expense', '["expenses"]'::jsonb, '"Expense" = khoản phải chi. Tính từ "expensive" (đắt) cùng gốc.', NULL, '{"sentence": "Food and transport are the main ___s for most students.", "hint": "e _ _ _ _ _ e"}'::jsonb);
INSERT INTO question_vocabularies (question_id, vocabulary_id, relation_type) VALUES (152, 51, 'TARGET');
INSERT INTO questions (id, content_type, skill, question_type, tier, question_text, answer, accepted_answers, explanation, audio_url, metadata) VALUES (153, 'VOCABULARY', 'WRITING', 'FILL_BLANK', 3, 'Điền một từ phù hợp vào chỗ trống', 'expense', '["expenses"]'::jsonb, 'Công ty chi trả mọi khoản chi đi lại → "expenses". "Budget" là số tiền dự định chi, không phải từng khoản đã tiêu.', NULL, '{"sentence": "The company will pay all travel ___s for the training course."}'::jsonb);
INSERT INTO question_vocabularies (question_id, vocabulary_id, relation_type) VALUES (153, 51, 'TARGET');
INSERT INTO questions (id, content_type, skill, question_type, tier, question_text, answer, accepted_answers, explanation, audio_url, metadata) VALUES (154, 'VOCABULARY', 'READING', 'MULT_CHOICE', 1, 'What does "reminder" mean?', 'lời/tin nhắc', '[]'::jsonb, '"reminder" /rɪˈmaɪndə(r)/ nghĩa là lời/tin nhắc. Ví dụ: I set a reminder on my phone to pay the bill.', NULL, '{"options": ["sự kiểm tra (kỹ lưỡng)", "(thuộc) khu dân cư", "lời/tin nhắc", "có sẵn; rảnh"]}'::jsonb);
INSERT INTO question_vocabularies (question_id, vocabulary_id, relation_type) VALUES (154, 52, 'TARGET');
INSERT INTO questions (id, content_type, skill, question_type, tier, question_text, answer, accepted_answers, explanation, audio_url, metadata) VALUES (155, 'VOCABULARY', 'WRITING', 'FILL_BLANK', 2, 'Điền từ còn thiếu (gợi ý: lời/tin nhắc)', 'reminder', '["reminders"]'::jsonb, '"Reminder" = thứ nhắc bạn nhớ. Gốc "remind" (nhắc nhở).', NULL, '{"sentence": "This is a friendly ___ that your rent is due on Friday.", "hint": "r _ _ _ _ _ _ r"}'::jsonb);
INSERT INTO question_vocabularies (question_id, vocabulary_id, relation_type) VALUES (155, 52, 'TARGET');
INSERT INTO questions (id, content_type, skill, question_type, tier, question_text, answer, accepted_answers, explanation, audio_url, metadata) VALUES (156, 'VOCABULARY', 'WRITING', 'FILL_BLANK', 3, 'Điền một từ phù hợp vào chỗ trống', 'reminder', '["reminders"]'::jsonb, 'Thư nhắc trả sách quá hạn → "reminder". "Receipt" là biên lai thanh toán, không dùng để nhắc trả sách.', NULL, '{"sentence": "The library sent a ___ because my books are two days late."}'::jsonb);
INSERT INTO question_vocabularies (question_id, vocabulary_id, relation_type) VALUES (156, 52, 'TARGET');
INSERT INTO questions (id, content_type, skill, question_type, tier, question_text, answer, accepted_answers, explanation, audio_url, metadata) VALUES (157, 'VOCABULARY', 'READING', 'MULT_CHOICE', 1, 'What does "postpone" mean?', 'hoãn lại', '[]'::jsonb, '"postpone" /pəˈspəʊn/ nghĩa là hoãn lại. Ví dụ: The meeting was postponed until next Tuesday.', NULL, '{"options": ["hàng người (xếp hàng chờ)", "thợ sửa ống nước", "lắp đặt", "hoãn lại"]}'::jsonb);
INSERT INTO question_vocabularies (question_id, vocabulary_id, relation_type) VALUES (157, 53, 'TARGET');
INSERT INTO questions (id, content_type, skill, question_type, tier, question_text, answer, accepted_answers, explanation, audio_url, metadata) VALUES (158, 'VOCABULARY', 'WRITING', 'FILL_BLANK', 2, 'Điền từ còn thiếu (gợi ý: hoãn lại)', 'postpone', '["postponed", "postpones"]'::jsonb, '"Postpone" = dời sang thời điểm sau. Post- (sau) + pone (đặt).', NULL, '{"sentence": "It is raining hard, so we will ___ the barbecue until Sunday.", "hint": "p _ _ _ _ _ _ e"}'::jsonb);
INSERT INTO question_vocabularies (question_id, vocabulary_id, relation_type) VALUES (158, 53, 'TARGET');
INSERT INTO questions (id, content_type, skill, question_type, tier, question_text, answer, accepted_answers, explanation, audio_url, metadata) VALUES (159, 'VOCABULARY', 'WRITING', 'FILL_BLANK', 3, 'Điền một từ phù hợp vào chỗ trống', 'postpone', '["postponed", "postpones"]'::jsonb, 'Buổi hoà nhạc dời sang ngày khác → "postponed". "Confirm" là xác nhận sẽ diễn ra — ngược nghĩa với tình huống.', NULL, '{"sentence": "The concert has been ___d because the singer is sick."}'::jsonb);
INSERT INTO question_vocabularies (question_id, vocabulary_id, relation_type) VALUES (159, 53, 'TARGET');
INSERT INTO questions (id, content_type, skill, question_type, tier, question_text, answer, accepted_answers, explanation, audio_url, metadata) VALUES (160, 'VOCABULARY', 'READING', 'MULT_CHOICE', 1, 'What does "confirm" mean?', 'xác nhận', '[]'::jsonb, '"confirm" /kənˈfɜːm/ nghĩa là xác nhận. Ví dụ: Please confirm your booking by email.', NULL, '{"options": ["xác nhận", "nhân viên thu ngân", "chỗ rò rỉ", "chỗ cất đồ; việc lưu trữ"]}'::jsonb);
INSERT INTO question_vocabularies (question_id, vocabulary_id, relation_type) VALUES (160, 54, 'TARGET');
INSERT INTO questions (id, content_type, skill, question_type, tier, question_text, answer, accepted_answers, explanation, audio_url, metadata) VALUES (161, 'VOCABULARY', 'WRITING', 'FILL_BLANK', 2, 'Điền từ còn thiếu (gợi ý: xác nhận)', 'confirm', '["confirms", "confirmed"]'::jsonb, '"Confirm" = xác nhận lại là đúng/sẽ diễn ra. Danh từ "confirmation".', NULL, '{"sentence": "Please call us to ___ your appointment one day before.", "hint": "c _ _ _ _ _ m"}'::jsonb);
INSERT INTO question_vocabularies (question_id, vocabulary_id, relation_type) VALUES (161, 54, 'TARGET');
INSERT INTO questions (id, content_type, skill, question_type, tier, question_text, answer, accepted_answers, explanation, audio_url, metadata) VALUES (162, 'VOCABULARY', 'WRITING', 'FILL_BLANK', 3, 'Điền một từ phù hợp vào chỗ trống', 'confirm', '["confirms", "confirmed"]'::jsonb, 'Email báo đơn hàng đã được nhận → "confirm". "Postpone" là hoãn lại, không hợp với đơn vừa nhận.', NULL, '{"sentence": "We will send you an email to ___ that your order has been received."}'::jsonb);
INSERT INTO question_vocabularies (question_id, vocabulary_id, relation_type) VALUES (162, 54, 'TARGET');
INSERT INTO questions (id, content_type, skill, question_type, tier, question_text, answer, accepted_answers, explanation, audio_url, metadata) VALUES (163, 'VOCABULARY', 'READING', 'MULT_CHOICE', 1, 'What does "available" mean?', 'có sẵn; rảnh', '[]'::jsonb, '"available" /əˈveɪləbl/ nghĩa là có sẵn; rảnh. Ví dụ: Is this jacket available in a smaller size?', NULL, '{"options": ["bền", "có sẵn; rảnh", "đổi (hàng, tiền)", "phòng/chỗ còn trống"]}'::jsonb);
INSERT INTO question_vocabularies (question_id, vocabulary_id, relation_type) VALUES (163, 55, 'TARGET');
INSERT INTO questions (id, content_type, skill, question_type, tier, question_text, answer, accepted_answers, explanation, audio_url, metadata) VALUES (164, 'VOCABULARY', 'WRITING', 'FILL_BLANK', 2, 'Điền từ còn thiếu (gợi ý: có sẵn; rảnh)', 'available', '[]'::jsonb, '"Available" = có thể mua/dùng/gặp được ngay. Với người: đang rảnh.', NULL, '{"sentence": "Sorry, the blue sofa is not ___ right now. It will arrive next week.", "hint": "a _ _ _ _ _ _ _ e"}'::jsonb);
INSERT INTO question_vocabularies (question_id, vocabulary_id, relation_type) VALUES (164, 55, 'TARGET');
INSERT INTO questions (id, content_type, skill, question_type, tier, question_text, answer, accepted_answers, explanation, audio_url, metadata) VALUES (165, 'VOCABULARY', 'WRITING', 'FILL_BLANK', 3, 'Điền một từ phù hợp vào chỗ trống', 'available', '[]'::jsonb, 'Hỏi người kia có rảnh để gọi không → "available". "Convenient" dùng cho thời điểm ("Is 3 p.m. convenient?"), không đi với "you are … for a call".', NULL, '{"sentence": "Are you ___ for a short call at three o''clock?"}'::jsonb);
INSERT INTO question_vocabularies (question_id, vocabulary_id, relation_type) VALUES (165, 55, 'TARGET');
INSERT INTO questions (id, content_type, skill, question_type, tier, question_text, answer, accepted_answers, explanation, audio_url, metadata) VALUES (166, 'VOCABULARY', 'READING', 'MULT_CHOICE', 1, 'What does "queue" mean?', 'hàng người (xếp hàng chờ)', '[]'::jsonb, '"queue" /kjuː/ nghĩa là hàng người (xếp hàng chờ). Ví dụ: There was a long queue at the post office.', NULL, '{"options": ["có sẵn đồ đạc", "lớp cách nhiệt/cách âm", "hàng người (xếp hàng chờ)", "thường xuyên"]}'::jsonb);
INSERT INTO question_vocabularies (question_id, vocabulary_id, relation_type) VALUES (166, 56, 'TARGET');
INSERT INTO questions (id, content_type, skill, question_type, tier, question_text, answer, accepted_answers, explanation, audio_url, metadata) VALUES (167, 'VOCABULARY', 'WRITING', 'FILL_BLANK', 2, 'Điền từ còn thiếu (gợi ý: hàng người (xếp hàng chờ))', 'queue', '["line", "queues"]'::jsonb, '"Queue" = hàng người chờ (Anh-Anh; Anh-Mỹ hay nói "line"). Chỉ đọc là /kjuː/ — bốn chữ cuối câm.', NULL, '{"sentence": "We stood in a ___ for twenty minutes to buy tickets.", "hint": "q _ _ _ e"}'::jsonb);
INSERT INTO question_vocabularies (question_id, vocabulary_id, relation_type) VALUES (167, 56, 'TARGET');
INSERT INTO questions (id, content_type, skill, question_type, tier, question_text, answer, accepted_answers, explanation, audio_url, metadata) VALUES (168, 'VOCABULARY', 'WRITING', 'FILL_BLANK', 3, 'Điền một từ phù hợp vào chỗ trống', 'queue', '["line", "queues"]'::jsonb, 'Hàng người chờ thanh toán quá dài → "queue". "Cashier" là nhân viên thu ngân, không "dài" được.', NULL, '{"sentence": "The ___ at the supermarket checkout was so long that I left my basket."}'::jsonb);
INSERT INTO question_vocabularies (question_id, vocabulary_id, relation_type) VALUES (168, 56, 'TARGET');
INSERT INTO questions (id, content_type, skill, question_type, tier, question_text, answer, accepted_answers, explanation, audio_url, metadata) VALUES (169, 'VOCABULARY', 'READING', 'MULT_CHOICE', 1, 'What does "cashier" mean?', 'nhân viên thu ngân', '[]'::jsonb, '"cashier" /kæˈʃɪə(r)/ nghĩa là nhân viên thu ngân. Ví dụ: The cashier gave me the wrong change.', NULL, '{"options": ["ở gần đó", "người đang ở (trong nhà/phòng)", "tiền hoàn lại", "nhân viên thu ngân"]}'::jsonb);
INSERT INTO question_vocabularies (question_id, vocabulary_id, relation_type) VALUES (169, 57, 'TARGET');
INSERT INTO questions (id, content_type, skill, question_type, tier, question_text, answer, accepted_answers, explanation, audio_url, metadata) VALUES (170, 'VOCABULARY', 'WRITING', 'FILL_BLANK', 2, 'Điền từ còn thiếu (gợi ý: nhân viên thu ngân)', 'cashier', '["cashiers"]'::jsonb, '"Cashier" là người nhận tiền ở quầy. Gốc "cash" (tiền mặt).', NULL, '{"sentence": "Take your items to the ___ to pay.", "hint": "c _ _ _ _ _ r"}'::jsonb);
INSERT INTO question_vocabularies (question_id, vocabulary_id, relation_type) VALUES (170, 57, 'TARGET');
INSERT INTO questions (id, content_type, skill, question_type, tier, question_text, answer, accepted_answers, explanation, audio_url, metadata) VALUES (171, 'VOCABULARY', 'WRITING', 'FILL_BLANK', 3, 'Điền một từ phù hợp vào chỗ trống', 'cashier', '["cashiers"]'::jsonb, 'Người quét hàng và đưa biên lai → "cashier". "Customer" là khách hàng, người nhận biên lai chứ không đưa.', NULL, '{"sentence": "The ___ scanned the groceries and handed me the receipt."}'::jsonb);
INSERT INTO question_vocabularies (question_id, vocabulary_id, relation_type) VALUES (171, 57, 'TARGET');
INSERT INTO questions (id, content_type, skill, question_type, tier, question_text, answer, accepted_answers, explanation, audio_url, metadata) VALUES (172, 'VOCABULARY', 'READING', 'MULT_CHOICE', 1, 'What does "exchange" mean?', 'đổi (hàng, tiền)', '[]'::jsonb, '"exchange" /ɪksˈtʃeɪndʒ/ nghĩa là đổi (hàng, tiền). Ví dụ: Can I exchange this shirt for a larger size?', NULL, '{"options": ["đổi (hàng, tiền)", "khoản vay mua nhà (thế chấp)", "gia hạn", "sự giảm giá"]}'::jsonb);
INSERT INTO question_vocabularies (question_id, vocabulary_id, relation_type) VALUES (172, 58, 'TARGET');
INSERT INTO questions (id, content_type, skill, question_type, tier, question_text, answer, accepted_answers, explanation, audio_url, metadata) VALUES (173, 'VOCABULARY', 'WRITING', 'FILL_BLANK', 2, 'Điền từ còn thiếu (gợi ý: đổi (hàng, tiền))', 'exchange', '["exchanged", "exchanges"]'::jsonb, '"Exchange" = đổi lấy cái khác. Khác "return" (trả lại để lấy tiền).', NULL, '{"sentence": "The jacket is too small. I''d like to ___ it for a bigger one.", "hint": "e _ _ _ _ _ _ e"}'::jsonb);
INSERT INTO question_vocabularies (question_id, vocabulary_id, relation_type) VALUES (173, 58, 'TARGET');
INSERT INTO questions (id, content_type, skill, question_type, tier, question_text, answer, accepted_answers, explanation, audio_url, metadata) VALUES (174, 'VOCABULARY', 'WRITING', 'FILL_BLANK', 3, 'Điền một từ phù hợp vào chỗ trống', 'exchange', '["exchanged", "exchanges"]'::jsonb, 'Được đổi hàng nhưng không được lấy lại tiền → "exchange". Nếu lấy lại tiền thì là "refund" — câu này nói rõ là không được.', NULL, '{"sentence": "You can ___ the item within 30 days, but you cannot get your money back."}'::jsonb);
INSERT INTO question_vocabularies (question_id, vocabulary_id, relation_type) VALUES (174, 58, 'TARGET');
INSERT INTO questions (id, content_type, skill, question_type, tier, question_text, answer, accepted_answers, explanation, audio_url, metadata) VALUES (175, 'VOCABULARY', 'READING', 'MULT_CHOICE', 1, 'What does "frequent" mean?', 'thường xuyên', '[]'::jsonb, '"frequent" /ˈfriːkwənt/ nghĩa là thường xuyên. Ví dụ: Buses are frequent during the morning rush hour.', NULL, '{"options": ["việc giao hàng", "thường xuyên", "bất động sản; tài sản", "nhà thầu (người nhận làm công trình)"]}'::jsonb);
INSERT INTO question_vocabularies (question_id, vocabulary_id, relation_type) VALUES (175, 59, 'TARGET');
INSERT INTO questions (id, content_type, skill, question_type, tier, question_text, answer, accepted_answers, explanation, audio_url, metadata) VALUES (176, 'VOCABULARY', 'WRITING', 'FILL_BLANK', 2, 'Điền từ còn thiếu (gợi ý: thường xuyên)', 'frequent', '[]'::jsonb, '"Frequent" = xảy ra nhiều lần. Trạng từ "frequently".', NULL, '{"sentence": "She is a ___ visitor to this library; she comes almost every day.", "hint": "f _ _ _ _ _ _ t"}'::jsonb);
