INSERT INTO questions (id, content_type, skill, question_type, tier, question_text, answer, accepted_answers, explanation, audio_url, metadata) VALUES (179, 'VOCABULARY', 'WRITING', 'FILL_BLANK', 2, 'Điền từ còn thiếu (gợi ý: ở gần đó)', 'nearby', '[]'::jsonb, '"Nearby" = ở gần. Có thể đứng trước danh từ ("a nearby shop") hoặc cuối câu ("There''s a shop nearby").', NULL, '{"sentence": "Is there a ___ pharmacy? I need some medicine.", "hint": "n _ _ _ _ y"}'::jsonb);
