INSERT INTO questions (id, content_type, skill, question_type, tier, question_text, answer, accepted_answers, explanation, audio_url, metadata) VALUES (180, 'VOCABULARY', 'WRITING', 'FILL_BLANK', 3, 'Điền một từ phù hợp vào chỗ trống', 'nearby', '[]'::jsonb, 'Nhiều nhà hàng ở gần đó, đứng cuối câu → "nearby". "Convenient" là tiện lợi, nhưng "there are many restaurants convenient" sai ngữ pháp.', NULL, '{"sentence": "The hotel is close to the station, and there are many restaurants ___."}'::jsonb);
