INSERT INTO questions (id, content_type, skill, question_type, tier, question_text, answer, accepted_answers, explanation, audio_url, metadata) VALUES (195, 'VOCABULARY', 'WRITING', 'FILL_BLANK', 3, 'Điền một từ phù hợp vào chỗ trống', 'assignment', '["assignments", "homework"]'::jsonb, 'Nộp bài được giao lên trang lớp → "assignment". "Lecture" là bài giảng của thầy, học sinh không nộp bài giảng.', NULL, '{"sentence": "Please upload your ___ to the class website before midnight."}'::jsonb);
