INSERT INTO questions (id, content_type, skill, question_type, tier, question_text, answer, accepted_answers, explanation, audio_url, metadata) VALUES (196, 'VOCABULARY', 'READING', 'MULT_CHOICE', 1, 'What does "deadline" mean?', 'hạn chót', '[]'::jsonb, '"deadline" /ˈdedlaɪn/ nghĩa là hạn chót. Ví dụ: The deadline for applications is March 31.', NULL, '{"options": ["hội thảo chuyên đề", "khuôn viên trường", "hạn chót", "tốt nghiệp"]}'::jsonb);
