INSERT INTO questions (id, content_type, skill, question_type, tier, question_text, answer, accepted_answers, explanation, audio_url, metadata) VALUES (197, 'VOCABULARY', 'WRITING', 'FILL_BLANK', 2, 'Điền từ còn thiếu (gợi ý: hạn chót)', 'deadline', '["deadlines"]'::jsonb, '"Deadline" = thời điểm cuối cùng phải xong. "Meet the deadline" = kịp hạn.', NULL, '{"sentence": "The ___ for the essay is tomorrow at 9 a.m., so I must finish it tonight.", "hint": "d _ _ _ _ _ _ e"}'::jsonb);
INSERT INTO question_vocabularies (question_id, vocabulary_id, relation_type) VALUES (197, 66, 'TARGET');
INSERT INTO questions (id, content_type, skill, question_type, tier, question_text, answer, accepted_answers, explanation, audio_url, metadata) VALUES (198, 'VOCABULARY', 'WRITING', 'FILL_BLANK', 3, 'Điền một từ phù hợp vào chỗ trống', 'deadline', '["deadlines"]'::jsonb, 'Trễ hạn nộp sẽ bị trừ điểm → "miss the deadline". "Schedule" là lịch, không ai "miss the schedule" để bị trừ điểm.', NULL, '{"sentence": "Students who miss the ___ will lose ten points."}'::jsonb);
INSERT INTO question_vocabularies (question_id, vocabulary_id, relation_type) VALUES (198, 66, 'TARGET');
INSERT INTO questions (id, content_type, skill, question_type, tier, question_text, answer, accepted_answers, explanation, audio_url, metadata) VALUES (199, 'VOCABULARY', 'READING', 'MULT_CHOICE', 1, 'What does "curriculum" mean?', 'chương trình học', '[]'::jsonb, '"curriculum" /kəˈrɪkjələm/ nghĩa là chương trình học. Ví dụ: Coding is now part of the school curriculum.', NULL, '{"options": ["giấy chứng nhận, chứng chỉ", "đăng ký", "khoa; phòng ban", "chương trình học"]}'::jsonb);
INSERT INTO question_vocabularies (question_id, vocabulary_id, relation_type) VALUES (199, 67, 'TARGET');
INSERT INTO questions (id, content_type, skill, question_type, tier, question_text, answer, accepted_answers, explanation, audio_url, metadata) VALUES (200, 'VOCABULARY', 'WRITING', 'FILL_BLANK', 2, 'Điền từ còn thiếu (gợi ý: chương trình học)', 'curriculum', '["curricula", "curriculums"]'::jsonb, '"Curriculum" là toàn bộ các môn và nội dung của một chương trình học. Số nhiều: "curricula".', NULL, '{"sentence": "The school changed its ___ to include more science classes.", "hint": "c _ _ _ _ _ _ _ _ m"}'::jsonb);
INSERT INTO question_vocabularies (question_id, vocabulary_id, relation_type) VALUES (200, 67, 'TARGET');
INSERT INTO questions (id, content_type, skill, question_type, tier, question_text, answer, accepted_answers, explanation, audio_url, metadata) VALUES (201, 'VOCABULARY', 'WRITING', 'FILL_BLANK', 3, 'Điền một từ phù hợp vào chỗ trống', 'curriculum', '["curricula", "curriculums"]'::jsonb, 'Lên kế hoạch nội dung học cho cả khoá → "curriculum". "Subject" chỉ là một môn, không phải cả chương trình.', NULL, '{"sentence": "Teachers are planning a new ___ for next year''s beginners."}'::jsonb);
