INSERT INTO questions (id, content_type, skill, question_type, tier, question_text, answer, accepted_answers, explanation, audio_url, metadata) VALUES (202, 'VOCABULARY', 'READING', 'MULT_CHOICE', 1, 'What does "scholarship" mean?', 'học bổng', '[]'::jsonb, '"scholarship" /ˈskɒləʃɪp/ nghĩa là học bổng. Ví dụ: She won a scholarship to study in Japan.', NULL, '{"options": ["học bổng", "sự có mặt (chuyên cần)", "nộp (bài, đơn)", "buổi định hướng (cho người mới)"]}'::jsonb);
