INSERT INTO questions (id, content_type, skill, question_type, tier, question_text, answer, accepted_answers, explanation, audio_url, metadata) VALUES (203, 'VOCABULARY', 'WRITING', 'FILL_BLANK', 2, 'Điền từ còn thiếu (gợi ý: học bổng)', 'scholarship', '["scholarships"]'::jsonb, '"Scholarship" = tiền tài trợ cho người học giỏi. "Scholar" là học giả.', NULL, '{"sentence": "He studied very hard and received a full ___ from the university.", "hint": "s _ _ _ _ _ _ _ _ _ p"}'::jsonb);
