INSERT INTO questions (id, content_type, skill, question_type, tier, question_text, answer, accepted_answers, explanation, audio_url, metadata) VALUES (204, 'VOCABULARY', 'WRITING', 'FILL_BLANK', 3, 'Điền một từ phù hợp vào chỗ trống', 'scholarship', '["scholarships"]'::jsonb, 'Khoản trả giúp nửa học phí → "scholarship". "Certificate" là giấy chứng nhận, không trả tiền học được.', NULL, '{"sentence": "Students with excellent grades can apply for a ___ that pays half the tuition."}'::jsonb);
