INSERT INTO questions (id, content_type, skill, question_type, tier, question_text, answer, accepted_answers, explanation, audio_url, metadata) VALUES (205, 'VOCABULARY', 'READING', 'MULT_CHOICE', 1, 'What does "graduate" mean?', 'tốt nghiệp', '[]'::jsonb, '"graduate" /ˈɡrædʒueɪt/ nghĩa là tốt nghiệp. Ví dụ: She will graduate from college next June.', NULL, '{"options": ["tham gia", "tốt nghiệp", "sách giáo khoa", "ôn lại; xem xét lại"]}'::jsonb);
