INSERT INTO questions (id, content_type, skill, question_type, tier, question_text, answer, accepted_answers, explanation, audio_url, metadata) VALUES (206, 'VOCABULARY', 'WRITING', 'FILL_BLANK', 2, 'Điền từ còn thiếu (gợi ý: tốt nghiệp)', 'graduate', '["graduates", "graduated"]'::jsonb, '"Graduate (from)" = học xong và nhận bằng. Danh từ "graduation" (lễ tốt nghiệp).', NULL, '{"sentence": "My brother will ___ from high school this summer.", "hint": "g _ _ _ _ _ _ e"}'::jsonb);
