INSERT INTO questions (id, content_type, skill, question_type, tier, question_text, answer, accepted_answers, explanation, audio_url, metadata) VALUES (208, 'VOCABULARY', 'READING', 'MULT_CHOICE', 1, 'What does "certificate" mean?', 'giấy chứng nhận, chứng chỉ', '[]'::jsonb, '"certificate" /səˈtɪfɪkət/ nghĩa là giấy chứng nhận, chứng chỉ. Ví dụ: You will receive a certificate after the training.', NULL, '{"options": ["kiến thức", "vắng mặt", "giấy chứng nhận, chứng chỉ", "thư viện"]}'::jsonb);
