INSERT INTO questions (id, content_type, skill, question_type, tier, question_text, answer, accepted_answers, explanation, audio_url, metadata) VALUES (209, 'VOCABULARY', 'WRITING', 'FILL_BLANK', 2, 'Điền từ còn thiếu (gợi ý: giấy chứng nhận, chứng chỉ)', 'certificate', '["certificates"]'::jsonb, '"Certificate" là giấy chứng nhận đã hoàn thành/đạt chuẩn. Động từ "certify".', NULL, '{"sentence": "Everyone who finishes the course gets a ___.", "hint": "c _ _ _ _ _ _ _ _ _ e"}'::jsonb);
