INSERT INTO questions (id, content_type, skill, question_type, tier, question_text, answer, accepted_answers, explanation, audio_url, metadata) VALUES (211, 'VOCABULARY', 'READING', 'MULT_CHOICE', 1, 'What does "attendance" mean?', 'sự có mặt (chuyên cần)', '[]'::jsonb, '"attendance" /əˈtendəns/ nghĩa là sự có mặt (chuyên cần). Ví dụ: Attendance is checked at the start of every class.', NULL, '{"options": ["người hướng dẫn, giảng viên", "môn học", "đủ trình độ, đủ tiêu chuẩn", "sự có mặt (chuyên cần)"]}'::jsonb);
