INSERT INTO questions (id, content_type, skill, question_type, tier, question_text, answer, accepted_answers, explanation, audio_url, metadata) VALUES (212, 'VOCABULARY', 'WRITING', 'FILL_BLANK', 2, 'Điền từ còn thiếu (gợi ý: sự có mặt (chuyên cần))', 'attendance', '[]'::jsonb, '"Attendance" = việc có mặt. Gốc "attend" (tham dự). "Take attendance" = điểm danh.', NULL, '{"sentence": "The teacher takes ___ every morning to see who is absent.", "hint": "a _ _ _ _ _ _ _ _ e"}'::jsonb);
