INSERT INTO questions (id, content_type, skill, question_type, tier, question_text, answer, accepted_answers, explanation, audio_url, metadata) VALUES (214, 'VOCABULARY', 'READING', 'MULT_CHOICE', 1, 'What does "textbook" mean?', 'sách giáo khoa', '[]'::jsonb, '"textbook" /ˈtekstbʊk/ nghĩa là sách giáo khoa. Ví dụ: Open your textbook to page 45.', NULL, '{"options": ["sách giáo khoa", "bạn cùng lớp", "điểm số; khối lớp", "ghi danh, đăng ký học"]}'::jsonb);
