INSERT INTO questions (id, content_type, skill, question_type, tier, question_text, answer, accepted_answers, explanation, audio_url, metadata) VALUES (217, 'VOCABULARY', 'READING', 'MULT_CHOICE', 1, 'What does "library" mean?', 'thư viện', '[]'::jsonb, '"library" /ˈlaɪbrəri/ nghĩa là thư viện. Ví dụ: The library closes at nine o''clock.', NULL, '{"options": ["học phí", "thư viện", "buổi hội thảo thực hành", "bằng tốt nghiệp"]}'::jsonb);
