INSERT INTO questions (id, content_type, skill, question_type, tier, question_text, answer, accepted_answers, explanation, audio_url, metadata) VALUES (218, 'VOCABULARY', 'WRITING', 'FILL_BLANK', 2, 'Điền từ còn thiếu (gợi ý: thư viện)', 'library', '["libraries"]'::jsonb, '"Library" = thư viện (mượn sách). Chú ý: hiệu sách là "bookstore", không phải library.', NULL, '{"sentence": "I borrowed three books from the school ___ yesterday.", "hint": "l _ _ _ _ _ y"}'::jsonb);
