INSERT INTO questions (id, content_type, skill, question_type, tier, question_text, answer, accepted_answers, explanation, audio_url, metadata) VALUES (220, 'VOCABULARY', 'READING', 'MULT_CHOICE', 1, 'What does "instructor" mean?', 'người hướng dẫn, giảng viên', '[]'::jsonb, '"instructor" /ɪnˈstrʌktə(r)/ nghĩa là người hướng dẫn, giảng viên. Ví dụ: Our yoga instructor is very patient.', NULL, '{"options": ["khuôn viên trường", "học kỳ", "người hướng dẫn, giảng viên", "hội thảo chuyên đề"]}'::jsonb);
