INSERT INTO questions (id, content_type, skill, question_type, tier, question_text, answer, accepted_answers, explanation, audio_url, metadata) VALUES (223, 'VOCABULARY', 'READING', 'MULT_CHOICE', 1, 'What does "classmate" mean?', 'bạn cùng lớp', '[]'::jsonb, '"classmate" /ˈklɑːsmeɪt/ nghĩa là bạn cùng lớp. Ví dụ: My classmate helped me with the homework.', NULL, '{"options": ["đăng ký", "khoa; phòng ban", "bài giảng", "bạn cùng lớp"]}'::jsonb);
