INSERT INTO questions (id, content_type, skill, question_type, tier, question_text, answer, accepted_answers, explanation, audio_url, metadata) VALUES (226, 'VOCABULARY', 'READING', 'MULT_CHOICE', 1, 'What does "workshop" mean?', 'buổi hội thảo thực hành', '[]'::jsonb, '"workshop" /ˈwɜːkʃɒp/ nghĩa là buổi hội thảo thực hành. Ví dụ: The writing workshop meets every Thursday.', NULL, '{"options": ["buổi hội thảo thực hành", "nộp (bài, đơn)", "buổi định hướng (cho người mới)", "bài tập/nhiệm vụ được giao"]}'::jsonb);
