INSERT INTO questions (id, content_type, skill, question_type, tier, question_text, answer, accepted_answers, explanation, audio_url, metadata) VALUES (229, 'VOCABULARY', 'READING', 'MULT_CHOICE', 1, 'What does "seminar" mean?', 'hội thảo chuyên đề', '[]'::jsonb, '"seminar" /ˈsemɪnɑː(r)/ nghĩa là hội thảo chuyên đề. Ví dụ: The marketing seminar will be held in Room 3.', NULL, '{"options": ["hạn chót", "hội thảo chuyên đề", "ôn lại; xem xét lại", "tham gia"]}'::jsonb);
