INSERT INTO questions (id, content_type, skill, question_type, tier, question_text, answer, accepted_answers, explanation, audio_url, metadata) VALUES (230, 'VOCABULARY', 'WRITING', 'FILL_BLANK', 2, 'Điền từ còn thiếu (gợi ý: hội thảo chuyên đề)', 'seminar', '["seminars"]'::jsonb, '"Seminar" = buổi thảo luận/trình bày về một chuyên đề, thường nhóm nhỏ.', NULL, '{"sentence": "Thirty managers attended a ___ on customer service.", "hint": "s _ _ _ _ _ r"}'::jsonb);
