INSERT INTO questions (id, content_type, skill, question_type, tier, question_text, answer, accepted_answers, explanation, audio_url, metadata) VALUES (231, 'VOCABULARY', 'WRITING', 'FILL_BLANK', 3, 'Điền một từ phù hợp vào chỗ trống', 'seminar', '["seminars"]'::jsonb, 'Đăng ký tham dự buổi chuyên đề, số chỗ có hạn → "seminar". "Semester" là học kỳ, không "có chỗ ngồi giới hạn".', NULL, '{"sentence": "Please register for the ___ by Friday because seats are limited."}'::jsonb);
