INSERT INTO questions (id, content_type, skill, question_type, tier, question_text, answer, accepted_answers, explanation, audio_url, metadata) VALUES (232, 'VOCABULARY', 'READING', 'MULT_CHOICE', 1, 'What does "register" mean?', 'đăng ký', '[]'::jsonb, '"register" /ˈredʒɪstə(r)/ nghĩa là đăng ký. Ví dụ: You must register before you can use the gym.', NULL, '{"options": ["vắng mặt", "chương trình học", "đăng ký", "kiến thức"]}'::jsonb);
