INSERT INTO questions (id, content_type, skill, question_type, tier, question_text, answer, accepted_answers, explanation, audio_url, metadata) VALUES (233, 'VOCABULARY', 'WRITING', 'FILL_BLANK', 2, 'Điền từ còn thiếu (gợi ý: đăng ký)', 'register', '["registers", "registered"]'::jsonb, '"Register" = ghi tên chính thức (lớp, sự kiện, tài khoản). Danh từ "registration".', NULL, '{"sentence": "New students should ___ at the front office on Monday.", "hint": "r _ _ _ _ _ _ r"}'::jsonb);
