INSERT INTO questions (id, content_type, skill, question_type, tier, question_text, answer, accepted_answers, explanation, audio_url, metadata) VALUES (234, 'VOCABULARY', 'WRITING', 'FILL_BLANK', 3, 'Điền một từ phù hợp vào chỗ trống', 'register', '["registers", "registered"]'::jsonb, 'Tạo tài khoản bằng mã sinh viên → "register". "Submit" là nộp bài/đơn, không dùng cho việc lập tài khoản.', NULL, '{"sentence": "To use the online library, you first need to ___ with your student number."}'::jsonb);
