INSERT INTO questions (id, content_type, skill, question_type, tier, question_text, answer, accepted_answers, explanation, audio_url, metadata) VALUES (235, 'VOCABULARY', 'READING', 'MULT_CHOICE', 1, 'What does "submit" mean?', 'nộp (bài, đơn)', '[]'::jsonb, '"submit" /səbˈmɪt/ nghĩa là nộp (bài, đơn). Ví dụ: Please submit your report by Friday.', NULL, '{"options": ["môn học", "đủ trình độ, đủ tiêu chuẩn", "học bổng", "nộp (bài, đơn)"]}'::jsonb);
