INSERT INTO questions (id, content_type, skill, question_type, tier, question_text, answer, accepted_answers, explanation, audio_url, metadata) VALUES (236, 'VOCABULARY', 'WRITING', 'FILL_BLANK', 2, 'Điền từ còn thiếu (gợi ý: nộp (bài, đơn))', 'submit', '["submits", "submitted", "hand in"]'::jsonb, '"Submit" = nộp chính thức (bài, đơn, hồ sơ). Trang trọng hơn "hand in".', NULL, '{"sentence": "You have to ___ your essay before the deadline.", "hint": "s _ _ _ _ t"}'::jsonb);
