INSERT INTO questions (id, content_type, skill, question_type, tier, question_text, answer, accepted_answers, explanation, audio_url, metadata) VALUES (237, 'VOCABULARY', 'WRITING', 'FILL_BLANK', 3, 'Điền một từ phù hợp vào chỗ trống', 'submit', '["submits", "submitted", "hand in"]'::jsonb, 'Gửi kèm thư giới thiệu cùng đơn → "submit". "Review" là xem lại, không phải nộp.', NULL, '{"sentence": "Applicants must ___ two letters of recommendation with their form."}'::jsonb);
