INSERT INTO questions (id, content_type, skill, question_type, tier, question_text, answer, accepted_answers, explanation, audio_url, metadata) VALUES (238, 'VOCABULARY', 'READING', 'MULT_CHOICE', 1, 'What does "review" mean?', 'ôn lại; xem xét lại', '[]'::jsonb, '"review" /rɪˈvjuː/ nghĩa là ôn lại; xem xét lại. Ví dụ: Let''s review the main points before the test.', NULL, '{"options": ["ôn lại; xem xét lại", "điểm số; khối lớp", "ghi danh, đăng ký học", "tốt nghiệp"]}'::jsonb);
