INSERT INTO questions (id, content_type, skill, question_type, tier, question_text, answer, accepted_answers, explanation, audio_url, metadata) VALUES (239, 'VOCABULARY', 'WRITING', 'FILL_BLANK', 2, 'Điền từ còn thiếu (gợi ý: ôn lại; xem xét lại)', 'review', '["reviews", "reviewed", "revise"]'::jsonb, '"Review" = xem lại để nhớ (ôn bài) hoặc để đánh giá. Re- (lại) + view (nhìn).', NULL, '{"sentence": "Before the exam, I ___ my notes from every lesson.", "hint": "r _ _ _ _ w"}'::jsonb);
