INSERT INTO questions (id, content_type, skill, question_type, tier, question_text, answer, accepted_answers, explanation, audio_url, metadata) VALUES (250, 'VOCABULARY', 'READING', 'MULT_CHOICE', 1, 'What does "diploma" mean?', 'bằng tốt nghiệp', '[]'::jsonb, '"diploma" /dɪˈpləʊmə/ nghĩa là bằng tốt nghiệp. Ví dụ: He received his high school diploma last year.', NULL, '{"options": ["bằng tốt nghiệp", "buổi định hướng (cho người mới)", "bài tập/nhiệm vụ được giao", "thư viện"]}'::jsonb);
