INSERT INTO questions (id, content_type, skill, question_type, tier, question_text, answer, accepted_answers, explanation, audio_url, metadata) VALUES (251, 'VOCABULARY', 'WRITING', 'FILL_BLANK', 2, 'Điền từ còn thiếu (gợi ý: bằng tốt nghiệp)', 'diploma', '["diplomas", "degree"]'::jsonb, '"Diploma" = bằng cấp khi học xong một chương trình. Khác "certificate" (chứng chỉ ngắn hạn).', NULL, '{"sentence": "After four years of study, she finally received her ___.", "hint": "d _ _ _ _ _ a"}'::jsonb);
