INSERT INTO questions (id, content_type, skill, question_type, tier, question_text, answer, accepted_answers, explanation, audio_url, metadata) VALUES (259, 'VOCABULARY', 'READING', 'MULT_CHOICE', 1, 'What does "orientation" mean?', 'buổi định hướng (cho người mới)', '[]'::jsonb, '"orientation" /ˌɔːriənˈteɪʃn/ nghĩa là buổi định hướng (cho người mới). Ví dụ: All new students must attend the orientation on Monday.', NULL, '{"options": ["đủ trình độ, đủ tiêu chuẩn", "học bổng", "buổi hội thảo thực hành", "buổi định hướng (cho người mới)"]}'::jsonb);
