INSERT INTO questions (id, content_type, skill, question_type, tier, question_text, answer, accepted_answers, explanation, audio_url, metadata) VALUES (261, 'VOCABULARY', 'WRITING', 'FILL_BLANK', 3, 'Điền một từ phù hợp vào chỗ trống', 'orientation', '[]'::jsonb, 'Buổi giải thích nội quy và chỉ chỗ cho người mới → "orientation". "Seminar" là buổi chuyên đề, không dành để làm quen nội quy.', NULL, '{"sentence": "The ___ session explains the school rules and shows you where everything is."}'::jsonb);
