INSERT INTO questions (id, content_type, skill, question_type, tier, question_text, answer, accepted_answers, explanation, audio_url, metadata) VALUES (262, 'VOCABULARY', 'READING', 'MULT_CHOICE', 1, 'What does "participate" mean?', 'tham gia', '[]'::jsonb, '"participate" /pɑːˈtɪsɪpeɪt/ nghĩa là tham gia. Ví dụ: Everyone is welcome to participate in the discussion.', NULL, '{"options": ["tham gia", "ghi danh, đăng ký học", "tốt nghiệp", "hội thảo chuyên đề"]}'::jsonb);
INSERT INTO question_vocabularies (question_id, vocabulary_id, relation_type) VALUES (262, 88, 'TARGET');
INSERT INTO questions (id, content_type, skill, question_type, tier, question_text, answer, accepted_answers, explanation, audio_url, metadata) VALUES (263, 'VOCABULARY', 'WRITING', 'FILL_BLANK', 2, 'Điền từ còn thiếu (gợi ý: tham gia)', 'participate', '["participates", "participated", "take part"]'::jsonb, '"Participate in" = góp mặt và cùng làm. Danh từ "participant" (người tham gia).', NULL, '{"sentence": "All students are encouraged to ___ in class discussions.", "hint": "p _ _ _ _ _ _ _ _ _ e"}'::jsonb);
INSERT INTO question_vocabularies (question_id, vocabulary_id, relation_type) VALUES (263, 88, 'TARGET');
INSERT INTO questions (id, content_type, skill, question_type, tier, question_text, answer, accepted_answers, explanation, audio_url, metadata) VALUES (264, 'VOCABULARY', 'WRITING', 'FILL_BLANK', 3, 'Điền một từ phù hợp vào chỗ trống', 'participate', '["participates", "participated", "take part"]'::jsonb, 'Nhân viên tham gia chương trình đào tạo → "participate in". "Attend" không đi với "in" — nói "attend the program", không phải "attend in".', NULL, '{"sentence": "Employees who ___ in the training program will receive a bonus."}'::jsonb);
INSERT INTO question_vocabularies (question_id, vocabulary_id, relation_type) VALUES (264, 88, 'TARGET');
INSERT INTO questions (id, content_type, skill, question_type, tier, question_text, answer, accepted_answers, explanation, audio_url, metadata) VALUES (265, 'VOCABULARY', 'READING', 'MULT_CHOICE', 1, 'What does "absent" mean?', 'vắng mặt', '[]'::jsonb, '"absent" /ˈæbsənt/ nghĩa là vắng mặt. Ví dụ: Three students were absent because of the flu.', NULL, '{"options": ["đăng ký", "vắng mặt", "học phí", "giấy chứng nhận, chứng chỉ"]}'::jsonb);
INSERT INTO question_vocabularies (question_id, vocabulary_id, relation_type) VALUES (265, 89, 'TARGET');
INSERT INTO questions (id, content_type, skill, question_type, tier, question_text, answer, accepted_answers, explanation, audio_url, metadata) VALUES (266, 'VOCABULARY', 'WRITING', 'FILL_BLANK', 2, 'Điền từ còn thiếu (gợi ý: vắng mặt)', 'absent', '[]'::jsonb, '"Absent (from)" = không có mặt. Danh từ "absence"; trái nghĩa "present".', NULL, '{"sentence": "Mai was ___ from class yesterday because she was sick.", "hint": "a _ _ _ _ t"}'::jsonb);
INSERT INTO question_vocabularies (question_id, vocabulary_id, relation_type) VALUES (266, 89, 'TARGET');
INSERT INTO questions (id, content_type, skill, question_type, tier, question_text, answer, accepted_answers, explanation, audio_url, metadata) VALUES (267, 'VOCABULARY', 'WRITING', 'FILL_BLANK', 3, 'Điền một từ phù hợp vào chỗ trống', 'absent', '[]'::jsonb, 'Vắng quá ba buổi → "absent". "Available" là rảnh/có sẵn — nghĩa gần như ngược lại.', NULL, '{"sentence": "If you are ___ for more than three lessons, you must talk to the instructor."}'::jsonb);
INSERT INTO question_vocabularies (question_id, vocabulary_id, relation_type) VALUES (267, 89, 'TARGET');
INSERT INTO questions (id, content_type, skill, question_type, tier, question_text, answer, accepted_answers, explanation, audio_url, metadata) VALUES (268, 'VOCABULARY', 'READING', 'MULT_CHOICE', 1, 'What does "qualified" mean?', 'đủ trình độ, đủ tiêu chuẩn', '[]'::jsonb, '"qualified" /ˈkwɒlɪfaɪd/ nghĩa là đủ trình độ, đủ tiêu chuẩn. Ví dụ: All our teachers are fully qualified.', NULL, '{"options": ["sự có mặt (chuyên cần)", "nộp (bài, đơn)", "đủ trình độ, đủ tiêu chuẩn", "học kỳ"]}'::jsonb);
INSERT INTO question_vocabularies (question_id, vocabulary_id, relation_type) VALUES (268, 90, 'TARGET');
INSERT INTO questions (id, content_type, skill, question_type, tier, question_text, answer, accepted_answers, explanation, audio_url, metadata) VALUES (269, 'VOCABULARY', 'WRITING', 'FILL_BLANK', 2, 'Điền từ còn thiếu (gợi ý: đủ trình độ, đủ tiêu chuẩn)', 'qualified', '[]'::jsonb, '"Qualified" = có bằng cấp/kỹ năng cần thiết. Danh từ "qualification".', NULL, '{"sentence": "Only ___ nurses can work in the hospital''s emergency room.", "hint": "q _ _ _ _ _ _ _ d"}'::jsonb);
INSERT INTO question_vocabularies (question_id, vocabulary_id, relation_type) VALUES (269, 90, 'TARGET');
INSERT INTO questions (id, content_type, skill, question_type, tier, question_text, answer, accepted_answers, explanation, audio_url, metadata) VALUES (270, 'VOCABULARY', 'WRITING', 'FILL_BLANK', 3, 'Điền một từ phù hợp vào chỗ trống', 'qualified', '[]'::jsonb, 'Giáo viên đủ tiêu chuẩn, có kinh nghiệm → "qualified". "Frequent" là thường xuyên, không nói về trình độ.', NULL, '{"sentence": "We are looking for a ___ math teacher with at least two years of experience."}'::jsonb);
INSERT INTO question_vocabularies (question_id, vocabulary_id, relation_type) VALUES (270, 90, 'TARGET');
